UPDATE procurement_operation_log
SET data_name = #{contractNo}
WHERE business_type = 1
  AND data_id = #{contractId}

mapper.select:
SELECT
FROM procurement_operation_log WHERE 1 = 1
ORDER BY create_time DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT data_id, MAX(create_time) AS create_time FROM procurement_operation_log WHERE business_type = 1 AND operation_type = 'URGE_SIGN' AND data_id IN
#{contractId}
GROUP BY data_id
